const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [[[31.25, 30.07],
      [31.25, 29.95],
      [31.40, 29.95],
      [31.40, 30.07]]], null, false);

  const start1 = '1984-07-01';
  const end1 = '1984-09-30'; // Extended to cover July and surrounding for more images
  const start2 = '2019-09-01';
  const end2 = '2019-11-30'; // Extended to cover September and surrounding for more images

  // 2. Data Acquisition & Check

  // Function to mask clouds for Landsat 5
  function maskL5L7Clouds(image) {
    const qa = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).select(['SR_B1', 'SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B7'])
      .rename(['B1', 'B2', 'B3', 'B4', 'B5', 'B7'])
      .copyProperties(image, ['system:time_start']);
  }

  // Function to mask clouds for Landsat 8/9
  function maskL8L9Clouds(image) {
    const qa = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'])
      .rename(['B1', 'B2', 'B3', 'B4', 'B5', 'B7'])
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDBI
  function calculateNDBI(image) {
    // For Landsat 5/7, B5 is SWIR1, B4 is NIR
    // For Landsat 8/9, B6 is SWIR1, B5 is NIR (after renaming to B7, B5)
    return image.normalizedDifference(['B7', 'B5']).rename('NDBI');
  }

  // Collection for 1984 (Landsat 5)
  let l5_collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_SR')
    .filterBounds(geometry)
    .filterDate(start1, end1)
    .map(maskL5L7Clouds)
    .map(calculateNDBI);

  const l5_size = await l5_collection.size().getInfo();
  if (l5_size === 0) {
    console.log(`No Landsat 5 images found for 1984 (${start1} to ${end1}).`);
    console.log("C1");
    return;
  }
  let ndbi1984 = l5_collection.median().clip(geometry);

  // Collection for 2019 (Landsat 8)
  let l8_collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
    .filterBounds(geometry)
    .filterDate(start2, end2)
    .map(maskL8L9Clouds)
    .map(calculateNDBI);

  const l8_size = await l8_collection.size().getInfo();
  if (l8_size === 0) {
    console.log(`No Landsat 8 images found for 2019 (${start2} to ${end2}).`);
    console.log("C1");
    return;
  }
  let ndbi2019 = l8_collection.median().clip(geometry);

  // 3. Processing & Calculation
  const scale = 30; // Landsat resolution
  const maxPixels = 1e9;

  // Calculate the mean NDBI for both periods
  const ndbi1984_mean = await ndbi1984.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDBI').getInfo();

  const ndbi2019_mean = await ndbi2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDBI').getInfo();

  // Validate pixel counts for the mean calculation (a proxy for C2)
  const count1984 = await ndbi1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDBI').getInfo();

  const count2019 = await ndbi2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDBI').getInfo();

  // 4. Validation & Final Answer
  if (ndbi1984_mean === null || ndbi2019_mean === null ||
      isNaN(ndbi1984_mean) || isNaN(ndbi2019_mean)) {
    console.log("Calculation resulted in None/NaN.");
    console.log("C3");
    return;
  }

  if (count1984 === 0 || count2019 === 0) {
    console.log(`1984 Valid Pixels: ${count1984}, 2019 Valid Pixels: ${count2019}`);
    console.log("No valid pixels after cloud masking or in bounds.");
    console.log("C2");
    return;
  }

  console.log(`1984 Images: ${l5_size}`);
  console.log(`2019 Images: ${l8_size}`);
  console.log(`1984 NDBI (Mean): ${ndbi1984_mean.toFixed(4)} (Pixels: ${count1984})`);
  console.log(`2019 NDBI (Mean): ${ndbi2019_mean.toFixed(4)} (Pixels: ${count2019})`);

  // An increase in mean NDBI indicates an increase in built-up area
  if (ndbi2019_mean > ndbi1984_mean) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
